using Servicio.RetazoMarket.Business.DTOs.Imagen;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;
namespace Servicio.RetazoMarket.Business.Services;public class ImagenService:IImagenService {private readonly IImagenDataService _consultas;private readonly IImagenAdministracionDataService _administracion;private readonly IProductoDataService _productos;public ImagenService(IImagenDataService consultas,IImagenAdministracionDataService administracion,IProductoDataService productos)=>(_consultas,_administracion,_productos)=(consultas,administracion,productos);public async Task<ImagenResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _consultas.ObtenerPorIdAsync(id,ct);return m is null?null:ImagenBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<ImagenResponse>> ObtenerPorProductoAsync(int id,CancellationToken ct=default)=>(await _consultas.ObtenerPorProductoAsync(id,ct)).Select(ImagenBusinessMapper.ToResponse).ToList();public async Task<ImagenResponse> CrearAsync(CrearImagenRequest r,CancellationToken ct=default){var e=ImagenValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoExiste(r.id_producto,ct);try{return ImagenBusinessMapper.ToResponse(await _administracion.CrearAsync(ImagenBusinessMapper.ToDataModel(r),ct));}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}public async Task<ImagenResponse?> ActualizarAsync(ActualizarImagenRequest r,CancellationToken ct=default){var e=ImagenValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoExiste(r.id_producto,ct);try{var m=await _administracion.ActualizarAsync(ImagenBusinessMapper.ToDataModel(r),ct);return m is null?null:ImagenBusinessMapper.ToResponse(m);}catch(InvalidOperationException ex){throw new ValidationException(ex.Message);}}private async Task ProductoExiste(int id,CancellationToken ct){if(await _productos.ObtenerPorIdAsync(id,ct) is null)throw new ValidationException("El producto no existe.");}}
